import React,{useCallback,useEffect,useMemo,useRef,useState} from 'react';
import{createRoot}from'react-dom/client';
import{Html5Qrcode}from'html5-qrcode';
import{LayoutDashboard,ArrowLeftRight,Wallet,ChartNoAxesCombined,Settings,Plus,House,Landmark,CreditCard,HandCoins,Target,CalendarDays,Bell,Search,ChevronDown,ChevronLeft,ChevronRight,ArrowUpRight,ArrowDownLeft,TrendingUp,TrendingDown,ShieldCheck,LockKeyhole,Eye,EyeOff,CloudOff,Cloud,RefreshCw,Download,AlertCircle,Check,CheckCircle2,Camera,Link2,X,Users,Menu,LogOut,Sun,Moon,Save,Trash2,ReceiptText,SlidersHorizontal,Info,Mail,Clock,FileDown}from'lucide-react';
import{db,saveTransaction,setSetting,setting}from'./db';
import{type Account,type Member,type Transaction,type Budget,type Loan,type Debt,type Goal,type Recurring,nextRecurringDate,type AccountType,type OperationType,accountTotals,balance,categorySummary,compact,derivePin,expenseCategories,fmt,id,incomeCategories,isVisible,loanMonths,localDay,monthOf,monthly,nextDue,parseMoney,salt}from'./domain';
import{api,validScriptUrl,gatewayUrl}from'./api';
