import './style.css';

type Tab='home'|'operations'|'accounts'|'schedule'|'budget'|'credits'|'debts'|'analytics'|'goals'|'settings';
type Modal='operation'|'account'|'recurring'|'budget'|'credit'|'debt'|'goal'|'member'|null;
type Snapshot={members:Member[];accounts:Account[];txs:Transaction[];budgets:Budget[];loans:Loan[];recurring:Recurring[];debts:Debt[];goals:Goal[];outbox:number};
const EMPTY:Snapshot={members:[],accounts:[],txs:[],budgets:[],loans:[],recurring:[],debts:[],goals:[],outbox:0};
const nav:{tab:Tab;label:string;icon:React.ComponentType<{size?:number;strokeWidth?:number}>}[]=[{tab:'home',label:'Главная',icon:LayoutDashboard},{tab:'operations',label:'Операции',icon:ArrowLeftRight},{tab:'accounts',label:'Счета и карты',icon:Wallet},{tab:'budget',label:'Бюджет',icon:CalendarDays},{tab:'schedule',label:'Платежи',icon:Clock},{tab:'credits',label:'Кредиты',icon:Landmark},{tab:'debts',label:'Долги',icon:HandCoins},{tab:'analytics',label:'Аналитика',icon:ChartNoAxesCombined},{tab:'goals',label:'Цели',icon:Target},{tab:'settings',label:'Настройки',icon:Settings}];
const accountTypes:{value:AccountType;label:string}[]=[{value:'debit',label:'Дебетовая карта / счёт'},{value:'cash',label:'Наличные'},{value:'savings',label:'Накопительный счёт'},{value:'credit',label:'Кредитная карта'},{value:'loan',label:'Кредитный долг'}];
const COLORS=['#18a99b','#7d8ded','#e9aa57','#d97c89','#657e9a','#a38ac9','#639b72','#eb8975','#76b4ca'];
const labelType=(t:AccountType)=>accountTypes.find(x=>x.value===t)?.label||t;
function useData(){const[data,setData]=useState<Snapshot>(EMPTY);const reload=useCallback(async()=>{const [members,accounts,txs,budgets,loans,recurring,debts,goals,outbox]=await Promise.all([db.members.toArray(),db.accounts.toArray(),db.transactions.toArray(),db.budgets.toArray(),db.loans.toArray(),db.recurring.toArray(),db.debts.toArray(),db.goals.toArray(),db.outbox.count()]);setData({members,accounts,txs:txs.sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)),budgets,loans,recurring,debts,goals,outbox})},[]);useEffect(()=>{void reload()},[reload]);return {...data,reload}}
function IconBox({children,tone='neutral'}:{children:React.ReactNode;tone?:'neutral'|'positive'|'negative'|'purple'}){return <span className={`iconbox ${tone}`}>{children}</span>}
function SmallEmpty({icon:Icon,title,detail,action}:{icon:React.ComponentType<{size?:number}>;title:string;detail:string;action?:React.ReactNode}){return <div className="empty"><span className="empty-icon"><Icon size={26}/></span><strong>{title}</strong><p>{detail}</p>{action}</div>}
function moneyInput(v:string,update:(v:string)=>void,placeholder='0,00'){return <div className="money-input"><input inputMode="decimal" autoComplete="off" value={v} onChange={e=>update(e.target.value)} placeholder={placeholder}/><b>₽</b></div>}
function App(){const data=useData();const[ready,setReady]=useState(false),[memberId,setMemberId]=useState<string|null>(null),[selectedId,setSelectedId]=useState(''),[pin,setPin]=useState(''),[pinError,setPinError]=useState(''),[failures,setFailures]=useState(0),[unlockAt,setUnlockAt]=useState(0),[onboardName,setOnboardName]=useState(''),[onboardPin,setOnboardPin]=useState(''),[onboardEmail,setOnboardEmail]=useState(''),[scriptUrl,setScriptUrl]=useState(''),[urlDraft,setUrlDraft]=useState(''),[scan,setScan]=useState(false),[tab,setTab]=useState<Tab>('home'),[modal,setModal]=useState<Modal>(null),[toast,setToast]=useState(''),[month,setMonth]=useState(localDay().slice(0,7)),[hideMoney,setHideMoney]=useState(false),[dark,setDark]=useState(false),[showMenu,setShowMenu]=useState(false),[formError,setFormError]=useState(''),[query,setQuery]=useState(''),[remindHour,setRemindHour]=useState(20),[remind,setRemind]=useState(false),[cloudToken,setCloudToken]=useState(''),[cloudMemberId,setCloudMemberId]=useState(''),[cloudStatus,setCloudStatus]=useState('Не подключено'),[syncing,setSyncing]=useState(false),[timeTick,setTimeTick]=useState(0),[dayDone,setDayDone]=useState(false);
const syncingRef=useRef(false);
const member=data.members.find(m=>m.id===memberId)||null;
const visible=data.accounts.filter(a=>member&&isVisible(a,member));
const visibleIds=new Set(visible.map(a=>a.id));
const txs=data.txs.filter(t=>visibleIds.has(t.accountId)||(t.type==='transfer'&&!!t.targetAccountId&&visibleIds.has(t.targetAccountId)));
const totals=accountTotals(visible,txs),sum=monthly(txs,month),topCats=categorySummary(txs,month),visibleLoans=data.loans.filter(x=>member&&(x.ownerId===member.id||member.role==='admin'));
const visibleRecurring=data.recurring.filter(r=>visibleIds.has(r.accountId)&&r.enabled).sort((a,b)=>a.nextDate.localeCompare(b.nextDate));
const periodBudget=data.budgets.filter(b=>b.month===month),budgetTotal=periodBudget.reduce((s,b)=>s+b.limit,0);
const remaining=budgetTotal-sum.expense;
const todays=data.txs.filter(t=>member&&t.actorId===member.id&&t.date===localDay());
const needsReminder=!!member?.remind&&new Date().getHours()>=member.remindHour&&todays.length===0&&!dayDone&&timeTick>=0;
const mask=(n:number)=>hideMoney?'•••••• ₽':fmt(n);
const warn=(msg:string)=>{setToast(msg);window.setTimeout(()=>setToast(''),4500)};
useEffect(()=>{Promise.all([setting('scriptUrl'),setting('dark'),setting('hideMoney')]).then(([u,d,h])=>{setScriptUrl(u);setUrlDraft(u);setDark(d==='true');setHideMoney(h==='true');setReady(true)})},[]);
useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';void setSetting('dark',String(dark))},[dark]);
useEffect(()=>{if(!member)return;setRemind(member.remind);setRemindHour(member.remindHour)},[memberId,data.members]);
useEffect(()=>{if(!memberId){setDayDone(false);return}void setting('dayConfirmed:'+memberId+':'+localDay()).then(v=>setDayDone(v==='true'))},[memberId,timeTick]);
useEffect(()=>{if(!scan)return;let active=true;let scanner:Html5Qrcode|null=null;try{scanner=new Html5Qrcode('qr-reader');const s=scanner;s.start({facingMode:'environment'},{fps:10,qrbox:{width:220,height:220}},value=>{if(active){setUrlDraft(value);setScan(false)}},()=>{}).catch(()=>{if(active){setScan(false);warn('Камера недоступна — вставьте ссылку вручную')}})}catch{setScan(false)}return()=>{active=false;if(scanner){const s=scanner;s.stop().catch(()=>{})}}},[scan]);
useEffect(()=>{if(!member||!needsReminder||!('Notification'in window)||Notification.permission!=='granted')return;
 const key=`notified:${member.id}:${localDay()}`;if(sessionStorage.getItem(key))return;
 const notify=async()=>{try{const registration=await navigator.serviceWorker?.ready;if(registration){await registration.showNotification('Мои Финансы',{body:'За сегодня ещё нет операций. Проверьте расходы и доходы.',icon:`${import.meta.env.BASE_URL}favicon.svg`,tag:key});sessionStorage.setItem(key,'yes')}}catch{/* Notification is optional; on-screen reminder remains available */}};
 void notify()},[needsReminder,memberId]);
useEffect(()=>{const i=window.setInterval(()=>setTimeTick(x=>x+1),60000);return()=>clearInterval(i)},[]);
async function confirmNoOperations(){if(!member)return;const day=localDay();try{await setSetting('dayConfirmed:'+member.id+':'+day,'true');setDayDone(true);if(cloudToken){await queueEntity('dayConfirm',{id:member.id+':'+day,ownerId:member.id,day});void runSync()}warn('День отмечен: операций не было')}catch(e){warn('Не удалось сохранить подтверждение')}}
async function runSync(t=cloudToken,u=scriptUrl,who=cloudMemberId){
 if(!t||!u||!who||syncingRef.current||!navigator.onLine)return;
 syncingRef.current=true;setSyncing(true);setCloudStatus('Синхронизация…');
 try{const result=await syncFamily(t,u,who);await data.reload();setDayDone((await setting('dayConfirmed:'+who+':'+localDay()))==='true');setCloudStatus(`Обновлено · отправлено ${result.uploaded}`)}
 catch(e){setCloudStatus(e instanceof Error?e.message:'Ошибка синхронизации')}
 finally{syncingRef.current=false;setSyncing(false)}
}
useEffect(()=>{if(!cloudToken||!cloudMemberId||cloudMemberId!==memberId)return;
 void runSync(cloudToken,scriptUrl,cloudMemberId);
 const handle=()=>{if(navigator.onLine&&document.visibilityState==='visible')void runSync(cloudToken,scriptUrl,cloudMemberId)};
 const timer=window.setInterval(handle,120000);window.addEventListener('online',handle);document.addEventListener('visibilitychange',handle);
 return()=>{clearInterval(timer);window.removeEventListener('online',handle);document.removeEventListener('visibilitychange',handle)}
},[cloudToken,cloudMemberId,memberId,scriptUrl]);
async function connectCloud(url:string,remoteId:string,remotePin:string){
 if(!validScriptUrl(url))throw Error('Некорректная ссылка Apps Script');
 const result=await cloudLogin(url,remoteId,remotePin);const user=result.user;
 const s=salt(),pinHash=await derivePin(remotePin,s);
 const member:Member={id:user.id,name:user.name,role:user.role,pinSalt:s,pinHash,email:user.email||'',remind:!!user.remind,remindHour:user.remindHour||20,createdAt:new Date().toISOString()};
 await db.members.put(member);await setSetting('cloudMember:'+user.id,'true');await setSetting('scriptUrl',url);
 await sealToken(user.id,remotePin,result.token,url);
 setScriptUrl(url);setUrlDraft(url);setCloudMemberId(user.id);setCloudToken(result.token);setMemberId(user.id);setSelectedId(user.id);setTab('home');
 await data.reload();setCloudStatus('Подключено · первая синхронизация');void runSync(result.token,url,user.id);
}

async function createAdmin(e:React.FormEvent){e.preventDefault();if(onboardName.trim().length<2){setPinError('Укажите имя');return}if(!/^\d{6}$/.test(onboardPin)){setPinError('PIN должен содержать 6 цифр');return}if(data.members.length){setPinError('Семья уже создана');return}if(urlDraft.trim()){try{const u=new URL(urlDraft.trim());if(u.protocol!=='https:'||u.hostname!=='script.google.com'||!/^\/macros\/s\/[\w-]+\/exec\/?$/.test(u.pathname))throw Error();await setSetting('scriptUrl',u.href);setScriptUrl(u.href)}catch{setPinError('Ссылка Apps Script должна заканчиваться на /exec');return}}const s=salt(),hash=await derivePin(onboardPin,s);const m:Member={id:id(),name:onboardName.trim(),role:'admin',pinSalt:s,pinHash:hash,email:onboardEmail.trim(),remind:false,remindHour:20,createdAt:new Date().toISOString()};await db.members.add(m);setSelectedId(m.id);setMemberId(m.id);setOnboardPin('');setPinError('');await data.reload();warn('Профиль создан на этом устройстве. Для облачной работы потребуется настройка синхронизации.')}
async function login(e:React.FormEvent){e.preventDefault();const m=data.members.find(x=>x.id===selectedId);if(!m)return setPinError('Выберите профиль');if(!m.pinHash||!m.pinSalt){try{if(!scriptUrl)throw Error('Сначала подключите семейную базу');await connectCloud(scriptUrl,m.id,pin);setPin('');setPinError('')}catch(e){setPinError(e instanceof Error?e.message:'Не удалось войти')}return}if(Date.now()<unlockAt)return setPinError('Слишком много попыток. Попробуйте позже.');if(!/^\d{6}$/.test(pin))return setPinError('Введите 6 цифр');const hash=await derivePin(pin,m.pinSalt);if(hash!==m.pinHash){const n=failures+1;setFailures(n);if(n>=5){setUnlockAt(Date.now()+60000);setFailures(0)}setPin('');setPinError(n>=5?'Вход временно заблокирован на 60 секунд':'Неверный PIN');return}setPinError('');setPin('');setFailures(0);setMemberId(m.id);setTab('home');
 if(await setting('cloudMember:'+m.id)==='true'&&scriptUrl){
  try{const result=await cloudLogin(scriptUrl,m.id,pin);await sealToken(m.id,pin,result.token,scriptUrl);setCloudToken(result.token);setCloudMemberId(m.id);setCloudStatus('Подключено');}
  catch(err){const cached=await unsealToken(m.id,pin,scriptUrl);if(cached){setCloudToken(cached);setCloudMemberId(m.id)}setCloudStatus('Сервер недоступен · локальный режим');}
 }
}
function signout(){setCloudToken('');setCloudMemberId('');setCloudStatus('Не подключено');setMemberId(null);setSelectedId(member?.id||'');setTab('home');setModal(null)}
const changeMonth=(n:number)=>{const [y,m]=month.split('-').map(Number);const d=new Date(y,m-1+n,1);setMonth(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)};
const monthLabel=new Date(Number(month.slice(0,4)),Number(month.slice(5))-1,1).toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
async function markRecurring(r:Recurring){
 if(!member||r.ownerId!==member.id)return warn('Отмечать чужой платеж нельзя');
 if(!visibleIds.has(r.accountId))return warn('Нет доступа к счету');
 if(!confirm(`Подтвердить ${r.type==='expense'?'расход':'доход'} «${r.name}» на ${fmt(r.amount)}?`))return;
 const now=new Date().toISOString(),next=nextRecurringDate(r.nextDate,r.frequency,r.dayOfMonth),active=r.frequency!=='once';
 const t:Transaction={id:id(),type:r.type,accountId:r.accountId,amount:r.amount,category:r.category,note:'По плану: '+r.name,date:localDay(),actorId:member.id,ownerId:member.id,createdAt:now,sync:'local'};
 try{await db.transaction('rw',db.transactions,db.recurring,db.outbox,async()=>{
 await db.transactions.add(t);await db.outbox.put({id:t.id,entity:'transaction',record:JSON.stringify(t),createdAt:now,attempts:0});
 await db.recurring.update(r.id,{nextDate:next,enabled:active});await queueEntity('recurring',{...r,nextDate:next,enabled:active})});
 await data.reload();warn('Операция проведена, план обновлён');void runSync();
 }catch(e){warn(e instanceof Error?e.message:'Ошибка записи')}
}
function openModal(which:Modal){setFormError('');setModal(which);setShowMenu(false)}
if(!ready)return <div className="splash"><Wallet size={38}/>Мои Финансы</div>;
if(data.members.length===0)return <div className="auth-shell"><div className="auth-info"><span className="brand-symbol"><Wallet size={31}/></span><h1>Финансы под контролем.</h1><p>Счета, кредиты, семейный бюджет и понятные отчёты — в одном удобном месте.</p><div className="auth-feature"><ShieldCheck size={18}/> Работа офлайн на вашем устройстве</div></div><form className="auth-card" onSubmit={createAdmin}><span className="eyebrow">ПЕРВОНАЧАЛЬНАЯ НАСТРОЙКА</span><h2>Создайте семейный профиль</h2><p>Для уже созданной семейной базы подключитесь по ссылке Apps Script и PIN. Для автономного режима можно создать локальный профиль.</p><CloudPanel initialUrl={urlDraft} onConnect={connectCloud}/><label>Ссылка Google Apps Script (можно добавить позже)</label><textarea rows={2} value={urlDraft} onChange={e=>setUrlDraft(e.target.value)} placeholder="https://script.google.com/macros/s/.../exec"/><button className="outline full" type="button" onClick={()=>setScan(v=>!v)}><Camera size={16}/>{scan?"Закрыть QR-сканер":"Сканировать QR"}</button>{scan&&<div id="qr-reader"/>}<label>Ваше имя</label><input required value={onboardName} onChange={e=>setOnboardName(e.target.value)} placeholder="Например, Даниил"/><label>PIN-код (6 цифр)</label><input type="password" inputMode="numeric" autoComplete="new-password" maxLength={6} value={onboardPin} onChange={e=>setOnboardPin(e.target.value.replace(/\D/g,''))} placeholder="••••••"/><label>Email для будущих напоминаний (необязательно)</label><input type="email" value={onboardEmail} onChange={e=>setOnboardEmail(e.target.value)} placeholder="name@example.com"/>{pinError&&<div className="inline-error">{pinError}</div>}<button className="primary full" type="submit">Создать семью <ChevronRight size={18}/></button><p className="fineprint"><LockKeyhole size={14}/> Локальный PIN не заменяет защищённую серверную авторизацию. До настройки синхронизации данные остаются на устройстве.</p></form></div>;
if(!member)return <div className="lock-screen"><div className="lock-panel"><span className="brand-symbol"><Wallet size={29}/></span><h1>С возвращением!</h1><p>Выберите члена семьи и введите личный PIN-код.</p><div className="member-grid">{data.members.map(m=><button key={m.id} className={`member-choice ${selectedId===m.id?'chosen':''}`} onClick={()=>{setSelectedId(m.id);setPin('');setPinError('')}}><span>{m.name.slice(0,1).toUpperCase()}</span><b>{m.name}</b><small>{m.role==='admin'?'Администратор':'Участник'}</small></button>)}</div><form onSubmit={login}><label>PIN-код</label><input autoFocus type="password" maxLength={6} inputMode="numeric" autoComplete="off" placeholder="Введите 6 цифр" value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))}/>{pinError&&<p className="inline-error">{pinError}</p>}<button className="primary full" disabled={!selectedId}>Войти <ChevronRight size={17}/></button></form><p className="fineprint">Не делитесь PIN. На общем устройстве после работы выходите из профиля.</p></div></div>;
const heading=nav.find(x=>x.tab===tab)?.label||'Мои Финансы';
return <div className="app-shell">
<aside className="sidebar"><div className="sidebar-brand"><span className="brand-symbol"><Wallet size={23}/></span><div><b>Мои Финансы</b><small>Семейный бюджет</small></div></div><div className="sidebar-caption">МОЯ ФИНАНСОВАЯ ПАНЕЛЬ</div><div className="sidebar-nav">{nav.map(({tab:t,label,icon:Icon})=><button key={t} className={tab===t?'active':''} onClick={()=>{setTab(t);setShowMenu(false)}}><Icon size={19}/>{label}{t==='operations'&&data.outbox>0&&<span className="nav-count">{data.outbox}</span>}</button>)}</div><div className="sidebar-bottom"><div className="sync-note"><CloudOff size={17}/><div><b>Локальный режим</b><small>Данные ещё не синхронизируются</small></div></div><button className="sidebar-user" onClick={signout}><span className="avatar">{member.name[0].toUpperCase()}</span><span><b>{member.name}</b><small>{member.role==='admin'?'Администратор':'Член семьи'}</small></span><LogOut size={17}/></button></div></aside>
<div className="main-area"><header className="topbar"><div className="topbar-title"><span className="small-eyebrow">СЕМЕЙНОЕ ПРОСТРАНСТВО</span><h1>{heading}</h1></div><div className="top-actions"><span className="cloud-status" title={cloudStatus}><Cloud size={16}/>{cloudToken?'Облако': 'Локально'}{data.outbox>0?' · '+data.outbox:''}</span><button className="icon-button" aria-label="Скрыть суммы" title="Скрыть суммы" onClick={()=>{setHideMoney(v=>{void setSetting('hideMoney',String(!v));return !v})}}>{hideMoney?<EyeOff size={19}/>:<Eye size={19}/>}</button><button className={`icon-button ${needsReminder?'alert':''}`} title="Напоминания" onClick={()=>setTab('settings')}><Bell size={19}/>{needsReminder&&<i/>}</button><button className="profile-button" onClick={signout}><span className="avatar">{member.name[0].toUpperCase()}</span><span>{member.name}</span><ChevronDown size={14}/></button></div></header>
<main className="content">
{tab==='home'&&<>
<div className="section-top"><div><h2>Финансовый обзор</h2><p>Всё важное о деньгах вашей семьи в одном месте.</p></div><MonthNav label={monthLabel} prev={()=>changeMonth(-1)} next={()=>changeMonth(1)}/></div>
{needsReminder&&<div className="reminder-banner"><Bell size={19}/><span><b>Проверьте финансы за сегодня</b><small>От вашего профиля пока нет записей. Если расходов не было, просто отметьте это.</small></span><div className="reminder-actions"><button className="primary" onClick={()=>openModal('operation')}>Добавить</button><button className="outline" onClick={()=>void confirmNoOperations()}>Нет операций</button></div></div>}
<div className="overview-grid"><section className="hero-balance"><div className="hero-top"><span>МОЙ КАПИТАЛ</span><span className="hero-chip"><span className="live-dot"/> {!navigator.onLine?'Без сети':cloudToken?'Облачная синхронизация':'Локальный режим'}</span></div><div className="hero-value">{mask(totals.assets+totals.liabilities)}</div><div className="hero-meta"><span>Деньги на счетах <b>{mask(totals.assets)}</b></span><span>Долговые счета <b>{mask(-totals.liabilities)}</b></span></div><button onClick={()=>openModal('operation')} className="hero-action"><Plus size={18}/> Новая операция</button><div className="hero-watermark"><Wallet size={130} strokeWidth={1}/></div></section><div className="metrics-grid"><Stat tone="positive" icon={<ArrowDownLeft size={20}/>} label="Доходы за месяц" value={mask(sum.income)} sub="Подтверждённые вами операции"/><Stat tone="negative" icon={<ArrowUpRight size={20}/>} label="Расходы за месяц" value={mask(sum.expense)} sub="Без переводов между счетами"/><Stat tone="purple" icon={<CalendarDays size={20}/>} label="Бюджет: остаток" value={mask(remaining)} sub={budgetTotal?'По установленным лимитам':'Добавьте лимиты бюджета'}/><Stat tone="neutral" icon={<TrendingUp size={20}/>} label="Денежный поток" value={mask(sum.income-sum.expense)} sub="Доходы минус расходы"/></div></div>
<div className="dashboard-grid"><section className="surface card-spending"><div className="card-title"><div><h3>Куда уходят деньги</h3><p>Расходы по категориям за {monthLabel}</p></div><button className="text-action" onClick={()=>setTab('analytics')}>Подробнее <ChevronRight size={15}/></button></div>{topCats.length?<div className="spending-body"><div className="donut" style={{background:donutGradient(topCats)}}><div><small>ВСЕГО РАСХОДОВ</small><b>{mask(sum.expense)}</b></div></div><div className="legend">{topCats.slice(0,5).map((c,i)=><div key={c.name} className="legend-item"><span style={{background:COLORS[i%COLORS.length]}}/><span>{c.name}</span><b>{Math.round(c.value/sum.expense*100)}%</b></div>)}</div></div>:<SmallEmpty icon={ChartNoAxesCombined} title="Пока нет расходов" detail="Добавьте операции, чтобы увидеть структуру трат."/>}</section><section className="surface card-activity"><div className="card-title"><div><h3>Последние операции</h3><p>История финансов семьи</p></div><button className="text-action" onClick={()=>setTab('operations')}>Все <ChevronRight size={15}/></button></div>{txs.slice(0,6).length?txs.slice(0,6).map(t=><TransactionRow key={t.id} t={t} accounts={visible} members={data.members} mask={mask}/>):<SmallEmpty icon={ReceiptText} title="Здесь появятся операции" detail="Начните с добавления счёта и первой записи."/>}</section></div>
<section className="surface account-strip"><div className="card-title"><div><h3>Мои счета</h3><p>Фактические остатки по операциям</p></div><button className="text-action" onClick={()=>setTab('accounts')}>Все счета <ChevronRight size={15}/></button></div><div className="accounts-mini">{totals.rows.slice(0,4).map(a=><div className="mini-account" key={a.id}><IconBox tone={a.type==='credit'||a.type==='loan'?'negative':'positive'}>{a.type==='cash'?<Wallet size={21}/>:<CreditCard size={21}/>}</IconBox><span><b>{a.name}</b><small>{labelType(a.type)}</small></span><strong>{mask(a.balance)}</strong></div>)}<button className="mini-add" onClick={()=>openModal('account')}><Plus size={19}/> Добавить счёт</button></div></section>
</>}
{tab==='operations'&&<><div className="section-top"><div><h2>Все операции</h2><p>Видно кто и с какого счёта вносил деньги.</p></div><button className="primary" onClick={()=>openModal('operation')}><Plus size={18}/> Добавить</button></div><div className="toolbar"><div className="search-field"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Категория, комментарий, участник..."/></div><MonthNav label={monthLabel} prev={()=>changeMonth(-1)} next={()=>changeMonth(1)}/></div><div className="surface list-panel">{txs.filter(t=>t.date.startsWith(month)&&(`${t.category} ${t.note} ${data.members.find(m=>m.id===t.actorId)?.name||''}`).toLocaleLowerCase().includes(query.toLocaleLowerCase())).map(t=><TransactionRow key={t.id} t={t} accounts={visible} members={data.members} mask={mask}/>)}{!txs.some(t=>t.date.startsWith(month))&&<SmallEmpty icon={ReceiptText} title="За этот месяц записей нет" detail="Добавьте доход, расход или перевод между счетами."/>}</div></>}
{tab==='accounts'&&<><div className="section-top"><div><h2>Счета и карты</h2><p>Наличные, банки и долги — с корректным балансом.</p></div><button className="primary" onClick={()=>openModal('account')}><Plus size={18}/> Добавить счёт</button></div><div className="overview-metrics"><Stat label="Активы" value={mask(totals.assets)} icon={<Wallet size={21}/>} tone="positive"/><Stat label="Обязательства" value={mask(-totals.liabilities)} icon={<CreditCard size={21}/>} tone="negative"/><Stat label="Чистый капитал" value={mask(totals.assets+totals.liabilities)} icon={<TrendingUp size={21}/>} tone="purple"/></div><div className="account-grid">{totals.rows.map(a=><div className={`account-card ${a.type==='credit'||a.type==='loan'?'liability':''}`} key={a.id}><div className="account-card-top"><IconBox tone={a.type==='credit'||a.type==='loan'?'negative':'positive'}>{a.type==='cash'?<Wallet size={21}/>:<Landmark size={21}/>}</IconBox><span className="type-pill">{a.shared?'Общий':'Личный'}</span></div><h3>{a.name}</h3><p>{labelType(a.type)}</p><strong>{mask(a.balance)}</strong><small>Стартовый остаток: {mask(a.opening)}</small></div>)}<button className="add-tile" onClick={()=>openModal('account')}><Plus size={24}/><b>Новый счёт</b><small>Наличные, карты, вклады или долги</small></button></div></>}
{tab==='budget'&&<><div className="section-top"><div><h2>Бюджет семьи</h2><p>Планируйте траты, чтобы деньги оставались под контролем.</p></div><MonthNav label={monthLabel} prev={()=>changeMonth(-1)} next={()=>changeMonth(1)}/></div><div className="overview-metrics"><Stat icon={<Target size={21}/>} tone="purple" label="План расходов" value={mask(budgetTotal)}/><Stat icon={<ArrowUpRight size={21}/>} tone="negative" label="Потрачено" value={mask(sum.expense)}/><Stat icon={<Wallet size={21}/>} tone="positive" label="Осталось" value={mask(remaining)}/></div><section className="surface budget-panel"><div className="card-title"><div><h3>Лимиты по категориям</h3><p>Расходы сравниваются с установленными лимитами</p></div><button className="outline" onClick={()=>openModal('budget')}><Plus size={17}/> Лимит</button></div>{periodBudget.length?periodBudget.map(b=>{const used=topCats.find(c=>c.name===b.category)?.value||0;const pct=Math.min(100,Math.round(used/Math.max(1,b.limit)*100));return <div className="budget-line" key={b.id}><div><b>{b.category}</b><span>{mask(used)} / {mask(b.limit)}</span></div><div className="track"><div className={pct>=100?'over':''} style={{width:`${pct}%`}}/></div><small>{used>b.limit?`Превышение ${mask(used-b.limit)}`:`Осталось ${mask(b.limit-used)}`}</small></div>}):<SmallEmpty icon={Target} title="Установите первый лимит" detail="Например, 25 000 ₽ на продукты или 10 000 ₽ на транспорт." action={<button className="outline" onClick={()=>openModal('budget')}>Добавить лимит</button>}/>}</section></>}
{tab==='schedule'&&<><div className="section-top"><div><h2>Платёжный календарь</h2><p>Регулярные доходы и обязательные платежи. Записи не влияют на баланс, пока вы не подтвердите факт.</p></div><button className="primary" onClick={()=>openModal('recurring')}><Plus size={18}/> Добавить</button></div>
 <div className="overview-metrics"><Stat icon={<Clock size={20}/>} tone="negative" label="Запланировано расходов" value={mask(visibleRecurring.filter(r=>r.type==='expense'&&r.nextDate<=localDay().slice(0,7)+'-31').reduce((sum,r)=>sum+r.amount,0))}/><Stat icon={<ArrowDownLeft size={20}/>} tone="positive" label="Запланировано доходов" value={mask(visibleRecurring.filter(r=>r.type==='income'&&r.nextDate<=localDay().slice(0,7)+'-31').reduce((sum,r)=>sum+r.amount,0))}/></div>
 <div className="surface list-panel">{visibleRecurring.map(r=><div className="debt-row" key={r.id}><IconBox tone={r.type==='income'?'positive':'negative'}>{r.type==='income'?<ArrowDownLeft size={20}/>:<CalendarDays size={20}/>}</IconBox><div><b>{r.name}</b><small>{r.nextDate} · {r.frequency==='once'?'Разовый':r.frequency==='weekly'?'Еженедельно':'Ежемесячно'} · {r.category}</small></div><strong>{mask(r.amount)}</strong>{r.ownerId===member.id&&<button className="outline small" onClick={()=>void markRecurring(r)}><Check size={16}/> Провести</button>}</div>)}{!visibleRecurring.length&&<SmallEmpty icon={CalendarDays} title="План пока пуст" detail="Добавьте зарплату, аренду, связь или подписки, чтобы видеть ближайшие платежи." action={<button className="outline" onClick={()=>openModal('recurring')}>Создать платеж</button>}/>}</div>
 </>}
{tab==='credits'&&<><div className="section-top"><div><h2>Кредиты и кредитные карты</h2><p>Остатки задолженности, ставки и платежи.</p></div><button className="primary" onClick={()=>openModal('credit')}><Plus size={18}/> Добавить</button></div><div className="loan-grid">{visibleLoans.map(l=>{const linked=visible.find(a=>a.id===l.accountId);const debt=linked?Math.max(0,-balance(linked,txs)):l.remaining;const months=loanMonths(debt,l.annualRate,l.payment);return <div className="surface loan-card" key={l.id}><div className="loan-title"><IconBox tone="negative">{l.kind==='card'?<CreditCard size={21}/>:<Landmark size={21}/>}</IconBox><div><b>{l.name}</b><small>{l.kind==='card'?'Кредитная карта':'Кредит'}</small></div></div><span className="loan-tag">{l.annualRate}% годовых</span><p>Текущая задолженность</p><strong className="loan-balance">{mask(debt)}</strong><div className="loan-info"><span>Платёж <b>{mask(l.payment)}</b></span><span>Число месяца <b>{l.dueDay}</b></span></div><div className="loan-info"><span>Расчётный срок <b>{Number.isFinite(months)?`${months} мес.`:'Недостаточный платёж'}</b></span></div><small className="hint">Остаток уточняется по проводкам связанного долгового счёта. Проценты и график банка необходимо сверять с договором.</small></div>})}<button className="add-tile" onClick={()=>openModal('credit')}><Plus size={24}/><b>Добавить кредит</b><small>Привязка к долговому счёту и график</small></button></div></>}
{tab==='debts'&&<><div className="section-top"><div><h2>Долги и займы</h2><p>Кому вы должны и кто должен вам.</p></div><button className="primary" onClick={()=>openModal('debt')}><Plus size={18}/> Добавить</button></div><div className="overview-metrics"><Stat icon={<ArrowUpRight size={20}/>} tone="negative" label="Я должен" value={mask(data.debts.filter(d=>d.direction==='owed').reduce((s,d)=>s+d.remaining,0))}/><Stat icon={<ArrowDownLeft size={20}/>} tone="positive" label="Мне должны" value={mask(data.debts.filter(d=>d.direction==='receivable').reduce((s,d)=>s+d.remaining,0))}/></div><div className="surface list-panel">{data.debts.filter(d=>d.ownerId===member.id).map(d=><div className="debt-row" key={d.id}><IconBox tone={d.direction==='owed'?'negative':'positive'}><HandCoins size={20}/></IconBox><div><b>{d.name}</b><small>{d.direction==='owed'?'Я должен':'Мне должны'} · до {d.dueDate||'без срока'}</small></div><strong>{mask(d.remaining)}</strong><button className="outline small" onClick={async()=>{const raw=prompt('Введите сумму погашения в ₽');if(!raw)return;const k=parseMoney(raw);if(!k||k>d.remaining)return warn('Недопустимая сумма');await db.transaction('rw',db.debts,db.outbox,async()=>{await db.debts.update(d.id,{remaining:d.remaining-k});await queueEntity('debt',{...d,remaining:d.remaining-k})});await data.reload();void runSync();warn('Долг обновлён. Денежное движение нужно провести отдельно.')}}>Погашение</button></div>)}{!data.debts.length&&<SmallEmpty icon={HandCoins} title="Долги не добавлены" detail="Ведите учёт личных займов и обязательств."/>}</div></>}
{tab==='analytics'&&<><div className="section-top"><div><h2>Аналитика расходов</h2><p>Разберитесь, на что расходуется семейный бюджет.</p></div><MonthNav label={monthLabel} prev={()=>changeMonth(-1)} next={()=>changeMonth(1)}/></div><div className="overview-metrics"><Stat icon={<ArrowDownLeft size={20}/>} tone="positive" label="Доходы" value={mask(sum.income)}/><Stat icon={<ArrowUpRight size={20}/>} tone="negative" label="Расходы" value={mask(sum.expense)}/><Stat icon={<TrendingUp size={20}/>} tone="purple" label="Разница" value={mask(sum.income-sum.expense)}/></div><div className="dashboard-grid"><div className="surface chart-card"><div className="card-title"><h3>Расходы по категориям</h3></div>{topCats.length?<><div className="donut large" style={{background:donutGradient(topCats)}}><div><small>РАСХОДЫ</small><b>{mask(sum.expense)}</b></div></div><div className="legend">{topCats.map((x,i)=><div className="legend-item" key={x.name}><span style={{background:COLORS[i%COLORS.length]}}/>{x.name}<b>{mask(x.value)}</b></div>)}</div></>:<SmallEmpty icon={ChartNoAxesCombined} title="Недостаточно данных" detail="Внесите расходы — они автоматически появятся в отчёте."/>}</div><div className="surface chart-card"><div className="card-title"><h3>Динамика за полгода</h3></div><div className="bar-chart">{Array.from({length:6},(_,i)=>{const [y,m]=month.split('-').map(Number);const dt=new Date(y,m-1-(5-i),1);const key=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`;const s=monthly(txs,key);return{label:dt.toLocaleDateString('ru-RU',{month:'short'}),...s}}).map((r,i,a)=>{const max=Math.max(...a.map(x=>Math.max(x.income,x.expense)),1);return <div className="bar-col" key={i}><div className="bar-pair"><span className="bar-income" style={{height:`${Math.max(2,r.income/max*100)}%`}} title={`Доход ${fmt(r.income)}`}/><span className="bar-expense" style={{height:`${Math.max(2,r.expense/max*100)}%`}} title={`Расход ${fmt(r.expense)}`}/></div><small>{r.label}</small></div>})}</div><div className="bar-key"><span><i className="income-dot"/> Доходы</span><span><i className="expense-dot"/> Расходы</span></div></div></div></>}
{tab==='goals'&&<><div className="section-top"><div><h2>Финансовые цели</h2><p>Крупные покупки и резервный фонд.</p></div><button className="primary" onClick={()=>openModal('goal')}><Plus size={18}/> Новая цель</button></div><div className="goal-grid">{data.goals.filter(g=>g.ownerId===member.id).map(g=><div className="surface goal-card" key={g.id}><IconBox tone="positive"><Target size={22}/></IconBox><h3>{g.name}</h3><p>Накоплено {mask(g.saved)} из {mask(g.target)}</p><div className="track"><div style={{width:`${Math.min(100,g.saved/g.target*100)}%`}}/></div><div className="goal-meta"><b>{Math.round(g.saved/g.target*100)}%</b><span>до {g.deadline||'без срока'}</span></div><button className="outline full" onClick={async()=>{const raw=prompt('Сколько добавить к цели, ₽?');if(!raw)return;const k=parseMoney(raw);if(!k)return warn('Недопустимая сумма');await db.transaction('rw',db.goals,db.outbox,async()=>{await db.goals.update(g.id,{saved:g.saved+k});await queueEntity('goal',{...g,saved:g.saved+k})});await data.reload();void runSync();warn('Прогресс цели обновлён. Банковский остаток не изменён.')}}>Отметить накопление</button></div>)}<button className="add-tile" onClick={()=>openModal('goal')}><Plus size={24}/><b>Создать цель</b><small>Деньги на отпуск, ремонт или резерв</small></button></div></>}
{tab==='settings'&&<><div className="section-top"><div><h2>Настройки семьи</h2><p>Профили, подключение Google и напоминания.</p></div></div><div className="settings-grid"><section className="surface setting-card"><div className="setting-header"><Cloud size={21}/><h3>Общая база семьи</h3></div><p>{cloudToken&&cloudMemberId===member.id?'Подключено: '+cloudStatus:'Подключите семейную Google-таблицу и PIN владельца профиля. Локальные записи остаются на устройстве до подтверждения сервером.'}</p><CloudPanel initialUrl={urlDraft} onConnect={connectCloud}/><button className="outline full" disabled={!cloudToken||syncing} onClick={()=>void runSync()}><RefreshCw size={17}/>{syncing?'Синхронизация…':'Синхронизировать сейчас'}</button><p className="hint">В общей локальной очереди: {data.outbox}. При входе отправляются только записи этого участника.</p></section><section className="surface setting-card"><div className="setting-header"><Users size={21}/><h3>Члены семьи</h3></div><p>У каждого собственный PIN и авторство операций.</p>{data.members.map(m=><div className="family-row" key={m.id}><span className="avatar">{m.name[0].toUpperCase()}</span><b>{m.name}</b><small>{m.role==='admin'?'Администратор':'Участник'}</small></div>)}{member.role==='admin'&&<button className="outline full" onClick={()=>openModal('member')}><Plus size={17}/> Добавить участника</button>}</section><section className="surface setting-card"><div className="setting-header"><Bell size={21}/><h3>Напоминания</h3></div><p>Напомнить внести сегодняшние расходы и доходы, если записей ещё нет.</p><label className="toggle-row"><span>Напоминать мне ежедневно</span><input type="checkbox" checked={remind} onChange={async e=>{const v=e.target.checked;setRemind(v);await db.members.update(member.id,{remind:v});if(cloudToken)await queueEntity('reminder',{id:'reminder:'+member.id,ownerId:member.id,enabled:v,hour:remindHour,email:member.email});await data.reload();void runSync()}}/></label><label>Email для напоминаний</label><input type="email" value={member.email||''} onChange={async e=>{await db.members.update(member.id,{email:e.target.value});await data.reload()}} onBlur={async()=>{if(cloudToken){await queueEntity('reminder',{id:'reminder:'+member.id,ownerId:member.id,enabled:remind,hour:remindHour,email:member.email});void runSync()}}} placeholder="name@example.com"/><label>Желаемое время</label><select value={remindHour} onChange={async e=>{const hour=Number(e.target.value);setRemindHour(hour);await db.members.update(member.id,{remindHour:hour});if(cloudToken)await queueEntity('reminder',{id:'reminder:'+member.id,ownerId:member.id,enabled:remind,hour,email:member.email});await data.reload();void runSync()}}>{Array.from({length:13},(_,i)=>i+10).map(h=><option value={h} key={h}>{String(h).padStart(2,'0')}:00</option>)}</select><button className="outline full" onClick={async()=>{if(!('Notification'in window)){warn('Этот браузер не поддерживает уведомления');return}const p=await Notification.requestPermission();warn(p==='granted'?'Уведомления разрешены, когда приложение активно. Для закрытого PWA доступны email-напоминания.':'Разрешение не получено')}}><Bell size={16}/> Разрешить уведомления в браузере</button><p className="hint">Напоминание на устройстве показывается при открытом PWA. Для закрытого приложения предусмотрен отдельный почтовый триггер Apps Script после его настройки.</p></section><section className="surface setting-card"><div className="setting-header"><Link2 size={21}/><h3>Google Apps Script</h3></div><p>Подключение через ссылку или QR при первом запуске. Ссылка запоминается на устройстве.</p><label>Адрес опубликованного веб-приложения</label><textarea value={urlDraft} onChange={e=>setUrlDraft(e.target.value)} rows={3} placeholder="https://script.google.com/macros/s/.../exec"/><button className="outline full" onClick={()=>setScan(v=>!v)}><Camera size={16}/> {scan?'Закрыть камеру':'Сканировать QR-код'}</button>{scan&&<div id="qr-reader"/>}<button className="primary full" onClick={async()=>{try{const u=new URL(urlDraft.trim());if(u.protocol!=='https:'||u.hostname!=='script.google.com'||!/^\/macros\/s\/[\w-]+\/exec\/?$/.test(u.pathname))throw Error();await setSetting('scriptUrl',u.href);setScriptUrl(u.href);setCloudToken('');setCloudMemberId('');setCloudStatus('Требуется вход по PIN');warn('Ссылка сохранена. Теперь подключите профиль выше по PIN.')}catch{warn('Введите правильную ссылку Apps Script, заканчивающуюся /exec')}}}><Save size={17}/> Сохранить ссылку</button><p className="hint">{scriptUrl?(cloudToken?'Соединение и авторизация активны.':'Адрес сохранён. Пройдите вход в общую базу по PIN.'):'Ссылка ещё не настроена.'}</p></section><section className="surface setting-card"><div className="setting-header"><ShieldCheck size={21}/><h3>Вид и безопасность</h3></div><label className="toggle-row"><span>Тёмная тема</span><input type="checkbox" checked={dark} onChange={e=>setDark(e.target.checked)}/></label><label className="toggle-row"><span>Скрывать денежные суммы</span><input type="checkbox" checked={hideMoney} onChange={e=>{setHideMoney(e.target.checked);void setSetting('hideMoney',String(e.target.checked))}}/></label><button className="outline full" onClick={()=>exportCSV(txs,visible,data.members)}><FileDown size={17}/> Экспорт операций CSV</button><button className="outline full" onClick={signout}><LogOut size={16}/> Выйти из профиля</button><p className="hint">Локальный PIN хранится как производный проверочный код, но сами данные IndexedDB пока не зашифрованы. Не используйте приложение для конфиденциальных данных до внедрения защищённого серверного режима.</p></section></div></>}
</main></div>
<nav className="mobile-nav"><button className={tab==='home'?'active':''} onClick={()=>setTab('home')}><House size={22}/><span>Главная</span></button><button className={tab==='operations'?'active':''} onClick={()=>setTab('operations')}><ArrowLeftRight size={22}/><span>Операции</span></button><button className="mobile-add" aria-label="Добавить операцию" onClick={()=>openModal('operation')}><Plus size={27}/></button><button className={tab==='budget'?'active':''} onClick={()=>setTab('budget')}><Target size={22}/><span>Бюджет</span></button><button className={showMenu?'active':''} onClick={()=>setShowMenu(v=>!v)}><Menu size={22}/><span>Ещё</span></button></nav>
{showMenu&&<div className="mobile-drawer"><div className="drawer-head"><b>Разделы</b><button className="icon-button" onClick={()=>setShowMenu(false)}><X size={20}/></button></div>{nav.filter(n=>!['home','operations','budget'].includes(n.tab)).map(({tab:t,label,icon:Icon})=><button key={t} onClick={()=>{setTab(t);setShowMenu(false)}}><Icon size={19}/>{label}<ChevronRight size={16}/></button>)}</div>}
{modal&&<EntryModal type={modal} cloudEnabled={!!cloudToken&&cloudMemberId===member.id} scriptUrl={scriptUrl} cloudToken={cloudToken} user={member} data={data} month={month} visibleAccounts={visible} error={formError} setError={setFormError} onClose={()=>setModal(null)} onSuccess={async msg=>{setModal(null);await data.reload();warn(msg);void runSync()}}/>}
{toast&&<div className="toast"><Info size={17}/>{toast}<button aria-label="Закрыть" onClick={()=>setToast('')}><X size={15}/></button></div>}
</div>}

function CloudPanel({initialUrl,onConnect}:{initialUrl:string;onConnect:(url:string,id:string,pin:string)=>Promise<void>}){
 const [url,setUrl]=useState(initialUrl),[profiles,setProfiles]=useState<Pick<CloudUser,'id'|'name'|'role'>[]>([]),[selected,setSelected]=useState(''),[pin,setPin]=useState(''),[status,setStatus]=useState(''),[busy,setBusy]=useState(false),[camera,setCamera]=useState(false);
 useEffect(()=>{if(initialUrl&&!url)setUrl(initialUrl)},[initialUrl]);
 useEffect(()=>{if(!camera)return;const reader=new Html5Qrcode('cloud-qr');let active=true;
 reader.start({facingMode:'environment'},{fps:8,qrbox:230},value=>{if(active){setUrl(value);setProfiles([]);setCamera(false)}},()=>{}).catch(()=>{setCamera(false);setStatus('Камера недоступна')});return()=>{active=false;reader.stop().catch(()=>{})}
 },[camera]);
 async function load(){setBusy(true);setStatus('');try{if(!validScriptUrl(url))throw Error('Укажите правильную ссылку /exec');const result=await getProfiles(url.trim());setProfiles(result);setSelected(result[0]?.id||'');if(!result.length)setStatus('В базе нет членов семьи. Запустите bootstrapOwner_() в Apps Script.')}catch(e){setStatus(String(e instanceof Error?e.message:e))}finally{setBusy(false)}}
 async function auth(e:React.FormEvent){e.preventDefault();if(!selected||!/^[0-9]{6}$/.test(pin))return setStatus('Выберите профиль и введите PIN из 6 цифр');setBusy(true);setStatus('');try{await onConnect(url.trim(),selected,pin);setPin('');setStatus('Подключено. Выполняется синхронизация.')}catch(e){setStatus(String(e instanceof Error?e.message:e))}finally{setBusy(false)}}
 return <div className="cloud-connect"><label>Ссылка опубликованного Apps Script</label><textarea rows={2} value={url} onChange={e=>{setUrl(e.target.value);setProfiles([])}} placeholder="https://script.google.com/macros/s/.../exec"/><div className="field-row"><button type="button" className="outline" onClick={()=>setCamera(v=>!v)}><Camera size={16}/> QR</button><button type="button" className="outline" disabled={busy||!gatewayUrl} onClick={()=>void load()}><RefreshCw size={16}/> Найти семью</button></div>{camera&&<div id="cloud-qr"/>}{!gatewayUrl&&<p className="inline-error">Для облачной работы администратору нужно развернуть Worker и задать VITE_API_URL в GitHub Actions.</p>}
 {profiles.length>0&&<form onSubmit={auth}><label>Кто входит?</label><select value={selected} onChange={e=>setSelected(e.target.value)}>{profiles.map(m=><option value={m.id} key={m.id}>{m.name} · {m.role==='admin'?'Администратор':'Участник'}</option>)}</select><label>Персональный PIN</label><input type="password" inputMode="numeric" autoComplete="off" maxLength={6} value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))}/><button className="primary full" disabled={busy}>Войти в семейную базу</button></form>}{status&&<p className="hint" role="status">{status}</p>}</div>
}
function MonthNav({label,prev,next}:{label:string;prev:()=>void;next:()=>void}){return <div className="month-nav"><button aria-label="Предыдущий месяц" onClick={prev}><ChevronLeft size={17}/></button><b>{label}</b><button aria-label="Следующий месяц" onClick={next}><ChevronRight size={17}/></button></div>}
function Stat({icon,label,value,sub,tone='neutral'}:{icon:React.ReactNode;label:string;value:string;sub?:string;tone?:'neutral'|'positive'|'negative'|'purple'}){return <div className="metric surface"><IconBox tone={tone}>{icon}</IconBox><div><small>{label}</small><strong>{value}</strong>{sub&&<span>{sub}</span>}</div></div>}
function donutGradient(items:{value:number}[]){const total=items.reduce((s,x)=>s+x.value,0)||1;let start=0;const parts=items.map((c,i)=>{const end=start+c.value/total*100;const stop=`${COLORS[i%COLORS.length]} ${start.toFixed(2)}% ${end.toFixed(2)}%`;start=end;return stop});return`conic-gradient(${parts.join(',')})`}
function TransactionRow({t,accounts,members,mask}:{t:Transaction;accounts:Account[];members:Member[];mask:(n:number)=>string}){const positive=t.type==='income';return <div className="transaction-row"><IconBox tone={positive?'positive':t.type==='expense'?'negative':'purple'}>{positive?<ArrowDownLeft size={20}/>:t.type==='expense'?<ArrowUpRight size={20}/>:<ArrowLeftRight size={20}/>}</IconBox><div className="transaction-main"><strong>{t.type==='transfer'?'Перевод':t.category}</strong><small>{accounts.find(a=>a.id===t.accountId)?.name||'Счёт'}{t.targetAccountId?` → ${accounts.find(a=>a.id===t.targetAccountId)?.name||'Счёт'}`:''} · {members.find(m=>m.id===t.actorId)?.name||'Участник'}{t.note?` · ${t.note}`:''}</small></div><div className="transaction-right"><strong className={positive?'positive-text':t.type==='expense'?'negative-text':''}>{positive?'+':t.type==='expense'?'−':''}{mask(t.amount)}</strong><small>{new Date(`${t.date}T12:00:00`).toLocaleDateString('ru-RU',{day:'2-digit',month:'short'})} · {t.sync==='synced'?'Отправлено':'На устройстве'}</small></div></div>}
function exportCSV(txs:Transaction[],accounts:Account[],members:Member[]){const esc=(s:string)=>'"'+s.replace(/"/g,'""')+'"';const rows=[['ID','Дата','Тип','Сумма, руб','Категория','Счёт','Получатель','Автор','Комментарий'],...txs.map(t=>[t.id,t.date,t.type,(t.amount/100).toFixed(2),t.category,accounts.find(a=>a.id===t.accountId)?.name||'',accounts.find(a=>a.id===t.targetAccountId)?.name||'',members.find(m=>m.id===t.actorId)?.name||'',t.note])];const csv='\ufeff'+rows.map(r=>r.map(x=>esc(String(x))).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`family-finance-${localDay()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function EntryModal({type,cloudEnabled,scriptUrl,cloudToken,user,data,month,visibleAccounts,error,setError,onClose,onSuccess}:{type:Exclude<Modal,null>;cloudEnabled:boolean;scriptUrl:string;cloudToken:string;user:Member;data:Snapshot;month:string;visibleAccounts:Account[];error:string;setError:(s:string)=>void;onClose:()=>void;onSuccess:(s:string)=>Promise<void>}){
const [name,setName]=useState(''),[value,setValue]=useState(''),[kind,setKind]=useState<OperationType>('expense'),[accountType,setAccountType]=useState<AccountType>('debit'),[source,setSource]=useState(visibleAccounts[0]?.id||''),[destination,setDestination]=useState(visibleAccounts[1]?.id||''),[category,setCategory]=useState('Продукты'),[note,setNote]=useState(''),[date,setDate]=useState(localDay()),[shared,setShared]=useState(true),[rate,setRate]=useState('18'),[payment,setPayment]=useState(''),[dueDay,setDueDay]=useState('15'),[frequency,setFrequency]=useState<Recurring['frequency']>('monthly'),[debtDirection,setDebtDirection]=useState<'owed'|'receivable'>('owed'),[deadline,setDeadline]=useState(''),[email,setEmail]=useState(''),[pin,setPin]=useState(''),[busy,setBusy]=useState(false);
async function submit(e:React.FormEvent){e.preventDefault();if(busy)return;setError('');const amount=parseMoney(value);setBusy(true);try{
if(type==='operation'){if(!amount)throw Error('Введите корректную сумму больше нуля');if(!source||!visibleAccounts.some(a=>a.id===source))throw Error('Выберите доступный счёт');if(kind==='transfer'&&(!destination||source===destination||!visibleAccounts.some(a=>a.id===destination)))throw Error('Выберите другой счёт назначения');const tx:Transaction={id:id(),type:kind,accountId:source,targetAccountId:kind==='transfer'?destination:undefined,amount,category:kind==='transfer'?'Перевод':category,note:note.trim().slice(0,300),date,actorId:user.id,ownerId:user.id,createdAt:new Date().toISOString(),sync:'local'};await saveTransaction(tx);await onSuccess('Операция сохранена локально')}
else if(type==='account'){if(name.trim().length<2)throw Error('Введите название счёта');const opening=value.trim()?parseMoney(value):0;if(opening===null)throw Error('Некорректный начальный остаток');const debt=accountType==='credit'||accountType==='loan';const acc:Account={id:id(),name:name.trim().slice(0,70),type:accountType,ownerId:user.id,shared:shared&&user.role==='admin',opening:debt?-(opening||0):(opening||0),createdAt:new Date().toISOString()};await db.transaction('rw',db.accounts,db.outbox,async()=>{await db.accounts.add(acc);await queueEntity('account',acc)});await onSuccess('Счёт создан')}
else if(type==='recurring'){if(!amount||!name.trim()||!source)throw Error('Заполните название, сумму и счёт');if(!date)throw Error('Укажите дату ближайшего платежа');const r:Recurring={id:id(),name:name.trim(),ownerId:user.id,accountId:source,type:kind==='transfer'?'expense':kind,category,amount,nextDate:date,frequency,enabled:true,dayOfMonth:Number(date.slice(8))};await db.transaction('rw',db.recurring,db.outbox,async()=>{await db.recurring.add(r);await queueEntity('recurring',r)});await onSuccess('Платёж добавлен в календарь')}
 else if(type==='budget'){if(!amount)throw Error('Укажите лимит');const key=`${month}:${category}`;await db.transaction('rw',db.budgets,db.outbox,async()=>{await db.budgets.put({id:key,month,category,limit:amount});await queueEntity('budget',{id:key,month,category,limit:amount,ownerId:user.id})});await onSuccess('Лимит бюджета сохранён')}
else if(type==='credit'){if(!name.trim()||!amount)throw Error('Укажите название и текущую задолженность');const pay=parseMoney(payment);if(!pay)throw Error('Укажите ежемесячный платёж');const annualRate=Number(rate.replace(',','.'));const day=Number(dueDay);if(!Number.isFinite(annualRate)||annualRate<0||annualRate>1000||day<1||day>31)throw Error('Проверьте ставку и дату платежа');const typeAcc:AccountType=accountType==='credit'?'credit':'loan';const accountId=id();await db.transaction('rw',db.accounts,db.loans,db.outbox,async()=>{const acc:Account={id:accountId,name:name.trim(),type:typeAcc,ownerId:user.id,shared,opening:-amount,createdAt:new Date().toISOString()};const loan:Loan={id:id(),name:name.trim(),ownerId:user.id,principal:amount,remaining:amount,annualRate,payment:pay,dueDay:day,kind:typeAcc==='credit'?'card':'loan',accountId};await db.accounts.add(acc);await db.loans.add(loan);await queueEntity('account',acc);await queueEntity('loan',loan)});await onSuccess('Кредит и связанный долговой счёт созданы')}
else if(type==='debt'){if(!name.trim()||!amount)throw Error('Укажите имя и сумму долга');const debt:Debt={id:id(),name:name.trim(),ownerId:user.id,direction:debtDirection,amount,remaining:amount,dueDate:deadline};await db.transaction('rw',db.debts,db.outbox,async()=>{await db.debts.add(debt);await queueEntity('debt',debt)});await onSuccess('Долг добавлен')}
else if(type==='goal'){if(!name.trim()||!amount)throw Error('Укажите цель и сумму');const goal:Goal={id:id(),name:name.trim(),ownerId:user.id,target:amount,saved:0,deadline};await db.transaction('rw',db.goals,db.outbox,async()=>{await db.goals.add(goal);await queueEntity('goal',goal)});await onSuccess('Цель добавлена')}
else if(type==='member'){if(user.role!=='admin')throw Error('Нет прав для добавления участников');if(name.trim().length<2||!/^\d{6}$/.test(pin))throw Error('Укажите имя и PIN из 6 цифр');const memberId=id();if(cloudEnabled){await api('createMember',{id:memberId,name:name.trim(),pin,email:email.trim()},cloudToken,scriptUrl)}const s=salt(),pinHash=await derivePin(pin,s);await db.members.add({id:memberId,name:name.trim(),role:'member',pinSalt:s,pinHash,email:email.trim(),remind:false,remindHour:20,createdAt:new Date().toISOString()});await onSuccess(cloudEnabled?'Участник создан на сервере':'Участник добавлен локально')}
}catch(err){setError(err instanceof Error?err.message:'Не удалось сохранить')}finally{setBusy(false)}}
const title={recurring:'Плановый платёж',operation:'Новая операция',account:'Новый счёт',budget:'Лимит бюджета',credit:'Кредит или кредитная карта',debt:'Новый долг',goal:'Финансовая цель',member:'Новый участник'}[type];
return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal"><div className="modal-header"><div><span className="small-eyebrow">МОИ ФИНАНСЫ</span><h2>{title}</h2></div><button className="icon-button" aria-label="Закрыть" onClick={onClose}><X size={22}/></button></div><form onSubmit={submit} className="modal-form">{type==='operation'&&<><div className="segmented">{(['expense','income','transfer'] as OperationType[]).map(k=><button type="button" key={k} className={kind===k?'active':''} onClick={()=>{setKind(k);setCategory(k==='income'?'Зарплата':'Продукты')}}>{k==='expense'?'Расход':k==='income'?'Доход':'Перевод'}</button>)}</div><label>Сумма</label>{moneyInput(value,setValue)}<label>Счёт списания / зачисления</label><select value={source} onChange={e=>setSource(e.target.value)}>{visibleAccounts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select>{kind==='transfer'?<><label>Счёт назначения</label><select value={destination} onChange={e=>setDestination(e.target.value)}><option value="">Выберите счёт</option>{visibleAccounts.filter(a=>a.id!==source).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select></>:<><label>Категория</label><select value={category} onChange={e=>setCategory(e.target.value)}>{(kind==='income'?incomeCategories:expenseCategories).map(c=><option key={c}>{c}</option>)}</select></>}<label>Дата</label><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><label>Комментарий</label><input value={note} onChange={e=>setNote(e.target.value)} placeholder="Необязательно" maxLength={300}/></>}
{type==='account'&&<><label>Название счёта</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Например, Сбербанк · основная"/><label>Тип счёта</label><select value={accountType} onChange={e=>setAccountType(e.target.value as AccountType)}>{accountTypes.map(t=><option key={t.value} value={t.value}>{t.label}</option>)}</select><label>{accountType==='credit'||accountType==='loan'?'Начальная задолженность':'Начальный остаток'}</label>{moneyInput(value,setValue)}<label className="toggle-row"><span>Общий семейный счёт</span><input type="checkbox" checked={shared} disabled={user.role!=='admin'} onChange={e=>setShared(e.target.checked)}/></label></>}
{type==='recurring'&&<><label>Название платежа</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Аренда, зарплата, интернет…"/><label>Тип</label><select value={kind} onChange={e=>{const k=e.target.value as 'income'|'expense';setKind(k);setCategory(k==='income'?'Зарплата':'Продукты')}}><option value="expense">Расход</option><option value="income">Доход</option></select><label>Сумма</label>{moneyInput(value,setValue)}<label>Счёт</label><select value={source} onChange={e=>setSource(e.target.value)}>{visibleAccounts.map(a=><option value={a.id} key={a.id}>{a.name}</option>)}</select><label>Категория</label><select value={category} onChange={e=>setCategory(e.target.value)}>{(kind==='income'?incomeCategories:expenseCategories).map(c=><option key={c}>{c}</option>)}</select><label>Дата следующего платежа</label><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><label>Периодичность</label><select value={frequency} onChange={e=>setFrequency(e.target.value as Recurring['frequency'])}><option value="monthly">Каждый месяц</option><option value="weekly">Каждую неделю</option><option value="once">Один раз</option></select><p className="hint">Запланированный платёж не списывает деньги автоматически. После фактической оплаты нажмите «Провести».</p></>}
{type==='budget'&&<><p className="subtle">Лимит на {month}. Повторное сохранение заменяет лимит выбранной категории.</p><label>Категория</label><select value={category} onChange={e=>setCategory(e.target.value)}>{expenseCategories.map(c=><option key={c}>{c}</option>)}</select><label>Планируемая сумма</label>{moneyInput(value,setValue)}</>}
{type==='credit'&&<><label>Название банка и продукта</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Например, Т-Банк Платинум"/><label>Тип</label><select value={accountType} onChange={e=>setAccountType(e.target.value as AccountType)}><option value="loan">Кредит</option><option value="credit">Кредитная карта</option></select><label>Остаток долга на сегодня</label>{moneyInput(value,setValue)}<div className="field-row"><div><label>Ставка годовых, %</label><input inputMode="decimal" value={rate} onChange={e=>setRate(e.target.value)}/></div><div><label>Дата платежа</label><input inputMode="numeric" value={dueDay} onChange={e=>setDueDay(e.target.value)}/></div></div><label>Платёж за месяц</label>{moneyInput(payment,setPayment)}<p className="hint">Приложение создаст связанный долговой счёт. Погашение основного долга проводите переводом на этот счёт, проценты — отдельным расходом.</p></>}
{type==='debt'&&<><label>Кому / кто должен</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Имя или назначение"/><label>Направление</label><select value={debtDirection} onChange={e=>setDebtDirection(e.target.value as 'owed'|'receivable')}><option value="owed">Я должен</option><option value="receivable">Мне должны</option></select><label>Сумма долга</label>{moneyInput(value,setValue)}<label>Срок возврата</label><input type="date" value={deadline} onChange={e=>setDeadline(e.target.value)}/></>}
{type==='goal'&&<><label>Название цели</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Например, Подушка безопасности"/><label>Сколько нужно накопить</label>{moneyInput(value,setValue)}<label>Желаемая дата</label><input type="date" value={deadline} onChange={e=>setDeadline(e.target.value)}/></>}
{type==='member'&&<><label>Имя члена семьи</label><input value={name} onChange={e=>setName(e.target.value)} placeholder="Имя"/><label>Его личный PIN (6 цифр)</label><input type="password" inputMode="numeric" maxLength={6} value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,''))}/><label>Email для напоминаний (необязательно)</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)}/><p className="hint">При активном подключении участник создаётся в общей базе и сможет войти с другого устройства по PIN.</p></>}
{error&&<div className="inline-error">{error}</div>}<div className="modal-footer"><button type="button" className="outline" onClick={onClose}>Отмена</button><button className="primary" type="submit" disabled={busy}>{busy?'Сохраняем...':'Сохранить'}<Check size={18}/></button></div></form></div></div>}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
